package com.google.gson;

import java.io.IOException;
import java.sql.Timestamp;
import java.text.DateFormat;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.Calendar;
import java.util.Date;
import java.util.GregorianCalendar;
import java.util.Locale;
import java.util.TimeZone;

import com.google.gson.internal.bind.util.ISO8601Utils;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import com.google.gson.stream.JsonWriter;

/**
 * This type adapter supports three subclasses of date: Date, Timestamp, and
 * java.sql.Date.
 *
 * @author Inderjeet Singh
 * @author Joel Leitch
 */
final class DefaultDateTypeAdapter extends TypeAdapter<Date> {

  private static final String SIMPLE_NAME = "DefaultDateTypeAdapter";

  private final Class<? extends Date> dateType;
  private final DateFormat enUsFormat;
  private final DateFormat localFormat;

  DefaultDateTypeAdapter(Class<? extends Date> dateType) {
    this(dateType,
        DateFormat.getDateTimeInstance(DateFormat.DEFAULT, DateFormat.DEFAULT, Locale.US),
        DateFormat.getDateTimeInstance(DateFormat.DEFAULT, DateFormat.DEFAULT));
  }

  DefaultDateTypeAdapter(Class<? extends Date> dateType, String datePattern) {
    this(dateType, new SimpleDateFormat(datePattern, Locale.US), new SimpleDateFormat(datePattern));
  }

  DefaultDateTypeAdapter(Class<? extends Date> dateType, int style) {
    this(dateType, DateFormat.getDateInstance(style, Locale.US), DateFormat.getDateInstance(style));
  }

  public DefaultDateTypeAdapter(int dateStyle, int timeStyle) {
    this(Date.class,
        DateFormat.getDateTimeInstance(dateStyle, timeStyle, Locale.US),
        DateFormat.getDateTimeInstance(dateStyle, timeStyle));
  }

  public DefaultDateTypeAdapter(Class<? extends Date> dateType, int dateStyle, int timeStyle) {
    this(dateType,
        DateFormat.getDateTimeInstance(dateStyle, timeStyle, Locale.US),
        DateFormat.getDateTimeInstance(dateStyle, timeStyle));
  }

  DefaultDateTypeAdapter(final Class<? extends Date> dateType, DateFormat enUsFormat, DateFormat localFormat) {
    if ( dateType != Date.class && dateType != java.sql.Date.class && dateType != Timestamp.class ) {
      throw new IllegalArgumentException("Date type must be one of " + Date.class + ", " + Timestamp.class + ", or " + java.sql.Date.class + " but was " + dateType);
    }
    this.dateType = dateType;
    this.enUsFormat = enUsFormat;
    this.localFormat = localFormat;
  }

  // These methods need to be synchronized since JDK DateFormat classes are not thread-safe
  // See issue 162
  @Override
  public void write(JsonWriter out, Date value) throws IOException {
    synchronized (localFormat) {
      Date instant = new Date(value.getTime());
      TimeZone formatTimeZone = enUsFormat.getTimeZone();
      Calendar sourceCalendar = new GregorianCalendar(formatTimeZone, Locale.US);
      sourceCalendar.setTime(instant);
      int era = sourceCalendar.get(Calendar.ERA);
      int year = sourceCalendar.get(Calendar.YEAR);
      int month = sourceCalendar.get(Calendar.MONTH);
      int dayOfMonth = sourceCalendar.get(Calendar.DAY_OF_MONTH);
      int hourOfDay = sourceCalendar.get(Calendar.HOUR_OF_DAY);
      int minute = sourceCalendar.get(Calendar.MINUTE);
      int second = sourceCalendar.get(Calendar.SECOND);
      int millisecond = sourceCalendar.get(Calendar.MILLISECOND);
      int zoneOffset = sourceCalendar.get(Calendar.ZONE_OFFSET);
      int dstOffset = sourceCalendar.get(Calendar.DST_OFFSET);

      Calendar normalizedCalendar = new GregorianCalendar(formatTimeZone, Locale.US);
      normalizedCalendar.clear();
      normalizedCalendar.set(Calendar.ERA, era);
      normalizedCalendar.set(Calendar.YEAR, year);
      normalizedCalendar.set(Calendar.MONTH, month);
      normalizedCalendar.set(Calendar.DAY_OF_MONTH, dayOfMonth);
      normalizedCalendar.set(Calendar.HOUR_OF_DAY, hourOfDay);
      normalizedCalendar.set(Calendar.MINUTE, minute);
      normalizedCalendar.set(Calendar.SECOND, second);
      normalizedCalendar.set(Calendar.MILLISECOND, millisecond);
      Date normalizedInstant = normalizedCalendar.getTime();

      String formatted = null;
      if (normalizedInstant.getTime() != instant.getTime()) {
        formatted = enUsFormat.format(instant);
      } else if (era == GregorianCalendar.BC) {
        formatted = enUsFormat.format(instant);
      } else if (year > 9999) {
        formatted = enUsFormat.format(instant);
      } else {
        try {
          int isoMonth = month + 1;
          int isoDay = dayOfMonth;
          int isoHour = hourOfDay;
          int isoMinute = minute;
          int isoSecond = second;
          int isoMillisecond = millisecond;
          StringBuilder isoBuilder = new StringBuilder(32);
          if (year < 10) {
            isoBuilder.append('0');
            isoBuilder.append('0');
            isoBuilder.append('0');
            isoBuilder.append((char) ('0' + year));
          } else if (year < 100) {
            isoBuilder.append('0');
            isoBuilder.append('0');
            isoBuilder.append((char) ('0' + (year / 10)));
            isoBuilder.append((char) ('0' + (year % 10)));
          } else if (year < 1000) {
            isoBuilder.append('0');
            isoBuilder.append((char) ('0' + (year / 100)));
            isoBuilder.append((char) ('0' + ((year / 10) % 10)));
            isoBuilder.append((char) ('0' + (year % 10)));
          } else {
            isoBuilder.append((char) ('0' + ((year / 1000) % 10)));
            isoBuilder.append((char) ('0' + ((year / 100) % 10)));
            isoBuilder.append((char) ('0' + ((year / 10) % 10)));
            isoBuilder.append((char) ('0' + (year % 10)));
          }
          isoBuilder.append('-');
          if (isoMonth < 10) {
            isoBuilder.append('0');
            isoBuilder.append((char) ('0' + isoMonth));
          } else {
            isoBuilder.append((char) ('0' + (isoMonth / 10)));
            isoBuilder.append((char) ('0' + (isoMonth % 10)));
          }
          isoBuilder.append('-');
          if (isoDay < 10) {
            isoBuilder.append('0');
            isoBuilder.append((char) ('0' + isoDay));
          } else {
            isoBuilder.append((char) ('0' + (isoDay / 10)));
            isoBuilder.append((char) ('0' + (isoDay % 10)));
          }
          isoBuilder.append('T');
          if (isoHour < 10) {
            isoBuilder.append('0');
            isoBuilder.append((char) ('0' + isoHour));
          } else {
            isoBuilder.append((char) ('0' + (isoHour / 10)));
            isoBuilder.append((char) ('0' + (isoHour % 10)));
          }
          isoBuilder.append(':');
          if (isoMinute < 10) {
            isoBuilder.append('0');
            isoBuilder.append((char) ('0' + isoMinute));
          } else {
            isoBuilder.append((char) ('0' + (isoMinute / 10)));
            isoBuilder.append((char) ('0' + (isoMinute % 10)));
          }
          isoBuilder.append(':');
          if (isoSecond < 10) {
            isoBuilder.append('0');
            isoBuilder.append((char) ('0' + isoSecond));
          } else {
            isoBuilder.append((char) ('0' + (isoSecond / 10)));
            isoBuilder.append((char) ('0' + (isoSecond % 10)));
          }
          isoBuilder.append('.');
          if (isoMillisecond < 10) {
            isoBuilder.append('0');
            isoBuilder.append('0');
            isoBuilder.append((char) ('0' + isoMillisecond));
          } else if (isoMillisecond < 100) {
            isoBuilder.append('0');
            isoBuilder.append((char) ('0' + (isoMillisecond / 10)));
            isoBuilder.append((char) ('0' + (isoMillisecond % 10)));
          } else {
            isoBuilder.append((char) ('0' + ((isoMillisecond / 100) % 10)));
            isoBuilder.append((char) ('0' + ((isoMillisecond / 10) % 10)));
            isoBuilder.append((char) ('0' + (isoMillisecond % 10)));
          }

          int offset = zoneOffset + dstOffset;
          if (offset != 0) {
            int absoluteOffset = offset;
            if (offset < 0) {
              isoBuilder.append('-');
              absoluteOffset = -offset;
            } else {
              isoBuilder.append('+');
            }
            int offsetHours = (absoluteOffset / (60 * 1000)) / 60;
            int offsetMinutes = (absoluteOffset / (60 * 1000)) % 60;
            if (offsetHours < 10) {
              isoBuilder.append('0');
              isoBuilder.append((char) ('0' + offsetHours));
              if (offsetMinutes < 10) {
                isoBuilder.append(':');
                isoBuilder.append('0');
                isoBuilder.append((char) ('0' + offsetMinutes));
              } else {
                isoBuilder.append(':');
                isoBuilder.append((char) ('0' + (offsetMinutes / 10)));
                isoBuilder.append((char) ('0' + (offsetMinutes % 10)));
              }
            } else {
              isoBuilder.append((char) ('0' + (offsetHours / 10)));
              isoBuilder.append((char) ('0' + (offsetHours % 10)));
              if (offsetMinutes < 10) {
                isoBuilder.append(':');
                isoBuilder.append('0');
                isoBuilder.append((char) ('0' + offsetMinutes));
              } else {
                isoBuilder.append(':');
                isoBuilder.append((char) ('0' + (offsetMinutes / 10)));
                isoBuilder.append((char) ('0' + (offsetMinutes % 10)));
              }
            }
          } else {
            isoBuilder.append('Z');
          }

          Date parsedIso = ISO8601Utils.parse(isoBuilder.toString(), new ParsePosition(0));
          if (enUsFormat instanceof SimpleDateFormat) {
            formatted = ((SimpleDateFormat) enUsFormat).format(parsedIso);
          } else {
            formatted = enUsFormat.format(parsedIso);
          }
        } catch (ParseException ignored) {
          formatted = null;
        }
      }

      if (formatted == null) {
        if (enUsFormat instanceof SimpleDateFormat) {
          formatted = ((SimpleDateFormat) enUsFormat).format(instant);
        } else {
          formatted = enUsFormat.format(instant);
        }
      }
      out.value(formatted);
    }
  }

  @Override
  public Date read(JsonReader in) throws IOException {
    if (in.peek() != JsonToken.STRING) {
      throw new JsonParseException("The date should be a string value");
    }
    Date date = deserializeToDate(in.nextString());
    if (dateType == Date.class) {
      return date;
    } else if (dateType == Timestamp.class) {
      return new Timestamp(date.getTime());
    } else if (dateType == java.sql.Date.class) {
      return new java.sql.Date(date.getTime());
    } else {
      // This must never happen: dateType is guarded in the primary constructor
      throw new AssertionError();
    }
  }

  private Date deserializeToDate(String s) {
    synchronized (localFormat) {
      try {
        return localFormat.parse(s);
      } catch (ParseException ignored) {}
      try {
        return enUsFormat.parse(s);
      } catch (ParseException ignored) {}
      try {
        return ISO8601Utils.parse(s, new ParsePosition(0));
      } catch (ParseException e) {
        throw new JsonSyntaxException(s, e);
      }
    }
  }

  @Override
  public String toString() {
    StringBuilder sb = new StringBuilder();
    sb.append(SIMPLE_NAME);
    sb.append('(').append(localFormat.getClass().getSimpleName()).append(')');
    return sb.toString();
  }
}

